using NetCalendy.Kata;

public sealed class CreateEventTypeSlugTests
{
    [Fact(DisplayName = "Handle_WhenSlugAlreadyExists_ShouldReturnConflict (ported from tests/NetCalendy.Application.Tests/EventTypes/CreateEventTypeHandlerTests.cs:45)")]
    public void Handle_WhenSlugAlreadyExists_ShouldReturnConflict()
    {
        var result = new CreateEventTypeHandler(_ => true).Handle("30-min-chat");

        Assert.True(result.IsFailure);
        Assert.Equal("EventType.SlugTaken", result.Error!.Code);
    }

    [Fact(DisplayName = "a duplicate slug is answered 409 Conflict by the status mapping (src/NetCalendy.Api/Extensions/ResultExtensions.cs:28)")]
    public void DuplicateSlug_MapsTo409()
    {
        var result = new CreateEventTypeHandler(_ => true).Handle("30-min-chat");

        Assert.Equal(409, ResultExtensions.StatusFor(result.Error!));
    }

    [Fact(DisplayName = "Handle_WithValidCommand_ShouldCreateEventType: a free slug succeeds (ported from tests/NetCalendy.Application.Tests/EventTypes/CreateEventTypeHandlerTests.cs:29)")]
    public void Handle_WithValidCommand_Succeeds()
    {
        var result = new CreateEventTypeHandler(_ => false).Handle("30-min-chat");

        Assert.True(result.IsSuccess);
        Assert.Null(result.Error);
    }

    [Fact(DisplayName = "a NotFound error is answered 404 (src/NetCalendy.Api/Extensions/ResultExtensions.cs:27)")]
    public void NotFound_MapsTo404()
    {
        Assert.Equal(404, ResultExtensions.StatusFor(Error.NotFound("EventType", Guid.Empty)));
    }
}
